<form method="get" class="filters visitor-filters"><input type="hidden" name="days" value="<?=$days?>"><input type="hidden" name="site" value="<?=esc($site)?>"><label>Država<select name="country"><option value="">Sve države</option><?php $choices=$countryCounts;foreach($choices as $code=>$count):?><option value="<?=esc($code)?>" <?=$filterCountry===$code?'selected':''?>><?=esc(($countries[$code]??$code).' ('.$count.')')?></option><?php endforeach;?></select></label><label>Traži IP, ID ili uređaj<input name="q" value="<?=esc($searchVisitor)?>" maxlength="80" placeholder="IP, #ID, Chrome…"></label><button>Pronađi posjetioca</button><a class="button outline" href="<?=esc(admin_url('', ['country'=>'','q'=>'','vp'=>1]))?>#visitor-list">Prikaži sve</a></form>
