<div class="table-wrap"><table><thead><tr><th>Posjetilac / IP</th><th>Država</th><th>Uređaj / preglednik</th><th>Posjete</th><th>Povratci</th><th>Modeli</th><th>Aktivno vrijeme</th><th>Zadnja aktivnost · Sarajevo</th></tr></thead><tbody><?php foreach($listedPeople as $person):?><tr><td><a class="visitor-link" href="<?=esc(admin_url($person['id']))?>"><strong>#<?=esc(strtoupper(substr($person['id'],0,8)))?></strong><small><?=esc($person['ip'])?></small></a></td><td><?=esc($countries[$person['country']]??$person['country'])?></td><td><?=esc($person['device'])?><small class="block"><?=esc($person['os'].' · '.$person['browser'])?></small></td><td><?=count($person['sessions'])?></td><td><?=max(0,count($person['sessions'])-1)?></td><td class="wrap"><?=esc(implode(', ',array_map(fn($id)=>$names[$id]??$id,array_keys($person['models']))))?:'—'?></td><td><?=duration($person['seconds'])?></td><td><?=esc(moment($person['last']))?></td></tr><?php endforeach;?></tbody></table></div>
